package pilot

import org.junit.jupiter.api.Assertions.assertEquals
import org.junit.jupiter.api.Assertions.assertNotEquals
import org.junit.jupiter.api.Assertions.assertThrows
import org.junit.jupiter.api.Test
import java.io.IOException
import java.net.SocketTimeoutException
import java.util.UUID

class PaymentServiceReviewTest {
    private enum class Step { OK, FAIL_BEFORE_CHARGE, LOST_AFTER_CHARGE, TIMEOUT_AFTER_CHARGE, REJECT }

    // Шлюз списывает не больше одного раза на ключ; сбой попытки задает сценарий.
    private class FakeGateway(vararg steps: Step) : PaymentGateway {
        private val script = ArrayDeque(steps.toList())
        val keys = mutableListOf<String>()
        val payments = linkedMapOf<String, Receipt>()

        override fun charge(request: Charge, idempotencyKey: String): Receipt {
            keys += idempotencyKey
            val step = script.removeFirstOrNull() ?: Step.OK
            when (step) {
                Step.REJECT -> throw RejectedCharge()
                Step.FAIL_BEFORE_CHARGE -> throw IOException("connect failed")
                else -> Unit
            }
            val receipt = payments.getOrPut(idempotencyKey) { Receipt("r${payments.size + 1}") }
            when (step) {
                Step.LOST_AFTER_CHARGE -> throw IOException("response lost")
                Step.TIMEOUT_AFTER_CHARGE -> throw SocketTimeoutException("read timed out")
                else -> return receipt
            }
        }
    }

    private val request = Charge("acc-1", 1000)
    private val randomKey = { UUID.randomUUID().toString() }

    @Test
    fun `retries a lost response with the same key and charges once`() {
        val gateway = FakeGateway(Step.LOST_AFTER_CHARGE, Step.LOST_AFTER_CHARGE, Step.OK)

        val receipt = PaymentService(gateway, randomKey).charge(request)

        assertEquals(3, gateway.keys.size)
        assertEquals(1, gateway.keys.distinct().size)
        assertEquals(1, gateway.payments.size)
        assertEquals(gateway.payments.values.single(), receipt)
    }

    @Test
    fun `rethrows IOException after exactly three attempts`() {
        val gateway = FakeGateway(Step.FAIL_BEFORE_CHARGE, Step.FAIL_BEFORE_CHARGE, Step.FAIL_BEFORE_CHARGE, Step.OK)

        assertThrows(IOException::class.java) { PaymentService(gateway, randomKey).charge(request) }

        assertEquals(3, gateway.keys.size)
        assertEquals(0, gateway.payments.size)
    }

    @Test
    fun `reports unknown outcome as IOException without a second charge`() {
        val gateway = FakeGateway(Step.LOST_AFTER_CHARGE, Step.LOST_AFTER_CHARGE, Step.LOST_AFTER_CHARGE, Step.OK)

        assertThrows(IOException::class.java) { PaymentService(gateway, randomKey).charge(request) }

        assertEquals(3, gateway.keys.size)
        assertEquals(1, gateway.payments.size)
    }

    @Test
    fun `retries IOException subclasses with the same key`() {
        val gateway = FakeGateway(Step.TIMEOUT_AFTER_CHARGE, Step.OK)

        val receipt = PaymentService(gateway, randomKey).charge(request)

        assertEquals(2, gateway.keys.size)
        assertEquals(1, gateway.keys.distinct().size)
        assertEquals(gateway.payments.values.single(), receipt)
    }

    @Test
    fun `does not retry RejectedCharge`() {
        val gateway = FakeGateway(Step.REJECT, Step.OK)

        assertThrows(RejectedCharge::class.java) { PaymentService(gateway, randomKey).charge(request) }

        assertEquals(1, gateway.keys.size)
        assertEquals(0, gateway.payments.size)
    }

    @Test
    fun `does not retry RejectedCharge that follows an IOException`() {
        val gateway = FakeGateway(Step.FAIL_BEFORE_CHARGE, Step.REJECT, Step.OK)

        assertThrows(RejectedCharge::class.java) { PaymentService(gateway, randomKey).charge(request) }

        assertEquals(2, gateway.keys.size)
        assertEquals(0, gateway.payments.size)
    }

    @Test
    fun `asks for one key per call regardless of attempts`() {
        var issued = 0
        val gateway = FakeGateway(Step.FAIL_BEFORE_CHARGE, Step.LOST_AFTER_CHARGE, Step.OK)

        PaymentService(gateway) { "key-${++issued}" }.charge(request)

        assertEquals(1, issued)
        assertEquals(listOf("key-1", "key-1", "key-1"), gateway.keys)
    }

    @Test
    fun `treats separate calls with identical data as separate payments`() {
        val gateway = FakeGateway(Step.LOST_AFTER_CHARGE, Step.OK, Step.OK)
        val service = PaymentService(gateway, randomKey)

        val first = service.charge(request)
        val second = service.charge(request)

        assertEquals(2, gateway.payments.size)
        assertEquals(2, gateway.keys.distinct().size)
        assertNotEquals(first, second)
    }
}
